window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["state-space-models"]={"title":"状态空间模型 SSM：用可控动态系统压缩长序列","subtitle":"从连续状态方程、离散化与卷积等价，到选择性扫描、线性复杂度、稳定性和随机访问边界。","thesis":"SSM 用一个随输入演化的状态概括历史，把长序列计算从位置两两交互改为线性扫描。结构化 SSM 可在训练时并行卷积、推理时递归更新；选择性 SSM 再让输入决定保留或遗忘什么。效率来自压缩，因此<b>精确回看、状态容量、数值稳定和硬件实现</b>决定真实上限。","quality":{"contractVersion":2,"examples":[{"section":2,"evidence":{"setup":"输入 x=[1,0,2] 和初始状态 h₀=0","rule":"Ā=0.8、B̄=1","steps":"0.8×0.8+2","interpretation":"同时含有过去的衰减记忆和当前输入"}}],"formulas":[{"id":"ssm-continuous-dynamics","section":1,"formulaIndex":1,"symbols":[{"name":"t","meaning":"连续时间变量","evidence":"t 是连续时间"},{"name":"x","meaning":"当前时刻输入","evidence":"x(t) 是当前输入"},{"name":"h","meaning":"概括此前历史的有限维状态","evidence":"h(t) 是概括此前历史的有限维状态"},{"name":"ḣ","meaning":"状态关于连续时间的变化率","evidence":"ḣ(t) 是状态随时间的变化率"},{"name":"y","meaning":"当前时刻模型输出","evidence":"y(t) 是当前输出"},{"name":"A","meaning":"控制状态自身连续演化的矩阵","evidence":"A 决定状态自身怎样演化"},{"name":"B","meaning":"把当前输入写入状态的矩阵","evidence":"B 把输入写入状态"},{"name":"C","meaning":"从内部状态读出输出的矩阵","evidence":"C 从状态读出输出"},{"name":"D","meaning":"把输入直接送至输出的直通矩阵","evidence":"D 提供输入到输出的直通路径"}]},{"id":"ssm-discrete-recurrence","section":2,"formulaIndex":1,"symbols":[{"name":"hₖ","meaning":"第 k 步更新后的状态","evidence":"hₖ₋₁ 与 hₖ 是更新前后的状态"},{"name":"hₖ₋₁","meaning":"第 k 步更新前的历史状态","evidence":"hₖ₋₁ 与 hₖ 是更新前后的状态"},{"name":"xₖ","meaning":"第 k 个离散时间步的输入","evidence":"xₖ 是第 k 步输入"},{"name":"Ā","meaning":"连续状态矩阵离散化后的一步转移矩阵","evidence":"连续矩阵离散化后的 Ā 与 B̄"},{"name":"B̄","meaning":"连续输入矩阵离散化后的写入矩阵","evidence":"连续矩阵离散化后的 Ā 与 B̄"},{"name":"e","meaning":"用于定义矩阵指数的自然指数函数","evidence":"符号 e 表示自然指数函数"},{"name":"Δ","meaning":"连续信号的采样步长","evidence":"Δ 是采样步长"},{"name":"A","meaning":"连续时间状态演化矩阵","evidence":"把连续演化 A 换算为一步状态转移"}]},{"id":"ssm-convolution-kernel","section":3,"formulaIndex":1,"symbols":[{"name":"yₖ","meaning":"第 k 个离散时间步的输出","evidence":"yₖ 是第 k 步输出"},{"name":"Σ","meaning":"把不同回看距离的输入贡献相加","evidence":"Σ 把从当前到最早位置的贡献相加"},{"name":"i","meaning":"相对当前输出向过去回看的距离","evidence":"i 是回看距离"},{"name":"k","meaning":"当前输出的离散时间步索引","evidence":"第 k 步输出"},{"name":"C","meaning":"从状态中读出输出的矩阵","evidence":"矩阵 C 负责从状态读出输出"},{"name":"Ā","meaning":"离散的一步状态转移矩阵","evidence":"Āⁱ 表示状态转移重复 i 次"},{"name":"B̄","meaning":"离散输入写入矩阵","evidence":"矩阵 B̄ 负责把历史输入写入状态"},{"name":"xₖ₋ᵢ","meaning":"距离当前输出 i 步的历史输入","evidence":"xₖ₋ᵢ 是 i 步前的输入"},{"name":"Kᵢ","meaning":"长卷积核在回看距离 i 的系数","evidence":"Kᵢ=CĀⁱB̄ 就是距离 i 对应的卷积核系数"}]},{"id":"selective-ssm-update","section":4,"formulaIndex":1,"symbols":[{"name":"xₜ","meaning":"当前位置的输入向量","evidence":"xₜ 是当前输入"},{"name":"fθ","meaning":"由参数 θ 控制的可学习选择函数","evidence":"fθ 是参数为 θ 的小型可学习函数"},{"name":"Δₜ","meaning":"由当前输入决定的当前位置步长","evidence":"当前位置的步长 Δₜ"},{"name":"Bₜ","meaning":"由当前输入决定的连续写入参数","evidence":"写入参数 Bₜ"},{"name":"Cₜ","meaning":"由当前输入决定的连续读出参数","evidence":"读出参数 Cₜ"},{"name":"hₜ","meaning":"当前位置更新后的有限维状态","evidence":"hₜ₋₁ 与 hₜ 是更新前后状态"},{"name":"hₜ₋₁","meaning":"当前位置更新前的历史状态","evidence":"hₜ₋₁ 与 hₜ 是更新前后状态"},{"name":"Ā","meaning":"依赖当前步长的离散状态转移","evidence":"Ā(Δₜ) 是由当前步长得到的离散状态转移"},{"name":"B̄ₜ","meaning":"当前位置对应的离散输入写入参数","evidence":"B̄ₜ 是对应离散写入参数"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"状态空间模型用有限维状态随输入连续演化来概括历史。","evidence":"输入驱动的动态系统"},"problem":{"answer":"它把任意长历史压缩成可递推更新的固定大小内部状态。","evidence":"一段历史怎样被压成有限维状态"},"inputOutput":{"answer":"输入连续时间信号 x(t)，输出状态 h(t) 和读出 y(t)。","evidence":"x(t) 是当前输入"},"mechanism":{"answer":"A 演化旧状态，B 写入输入，C 读出状态，D 提供直通输出。","evidence":"矩阵描述物理动态"},"interpretation":{"answer":"状态保存的是训练任务认为有用的历史摘要，而不是原输入副本。","evidence":"用于保存对任务有用的历史"},"boundary":{"answer":"有限维状态意味着信息被压缩，能保存多少取决于容量与动力学。","evidence":"概括此前历史的有限维状态"}},{"section":2,"definition":{"answer":"离散化把连续动力学按采样步长转换成逐 token 状态递推。","evidence":"手算离散化后的序列递推"},"problem":{"answer":"它让连续时间方程能处理离散序列且保持正确时间尺度。","evidence":"采样间隔改变时"},"inputOutput":{"answer":"输入旧状态、当前输入和采样步长，输出新状态及离散转移参数。","evidence":"更新前后的状态"},"mechanism":{"answer":"矩阵指数和离散化规则将 A、B 与 Δ 组合为 Ā、B̄。","evidence":"零阶保持等离散化方法会同时计算 Ā、B̄"},"interpretation":{"answer":"温度例第三步的 2.64 是衰减后旧状态 0.64 加当前异常 2。","evidence":"衰减为 0.64，再加当前输入 2"},"boundary":{"answer":"采样频率变化却不重算参数会改变模型时间尺度，递推也可能爆炸。","evidence":"若采样频率改变而不重算"}},{"section":3,"definition":{"answer":"线性时不变 SSM 的递推可展开成由动力学生成核的一维长卷积。","evidence":"同一线性 SSM 也可以看成一维卷积"},"problem":{"answer":"该等价视角让训练整段序列时可避免逐步串行递归。","evidence":"递归难并行，训练时如何一次处理整段"},"inputOutput":{"answer":"输入整段 x 与卷积核 K，输出所有时间步 y；流式时则维护状态 h。","evidence":"训练时可构造卷积核"},"mechanism":{"answer":"反复代入递推得到 Kᵢ=CĀⁱB̄，再汇总每个历史输入的贡献。","evidence":"反复代入可得"},"interpretation":{"answer":"递推适合 O(1) 增量状态更新，卷积或扫描适合训练吞吐。","evidence":"取决于训练吞吐还是流式延迟"},"boundary":{"answer":"固定卷积等价只适用于线性时不变参数，选择性会破坏其简单形式。","evidence":"同一线性系统的两种计算顺序"}},{"section":4,"definition":{"answer":"选择性 SSM 让步长、写入或读出参数依赖当前输入内容。","evidence":"按内容决定写入与遗忘"},"problem":{"answer":"它解决固定记忆规则难以只保留特定内容 token 的问题。","evidence":"只记住红色 token"},"inputOutput":{"answer":"输入当前 xₜ 与旧 hₜ₋₁，输出内容相关参数和新状态 hₜ。","evidence":"它输出当前位置的步长"},"mechanism":{"answer":"小型函数 fθ 由 xₜ 生成选择参数，再据此离散并更新状态。","evidence":"使相同距离的输入能被不同程度保留"},"interpretation":{"answer":"不同 token 可具有不同保留强度，表示模型按内容改变记忆时间尺度。","evidence":"内容选择力增强"},"boundary":{"answer":"输入依赖破坏固定卷积核，且有限状态容量并未因此消失。","evidence":"仍把历史压进有限状态"}},{"section":5,"definition":{"answer":"脉冲响应展示单次输入对未来状态随距离指数衰减的曲线。","evidence":"遗忘门改变脉冲的有效记忆长度"},"problem":{"answer":"它把抽象状态保留率转为早期事件还能影响多久的直观量。","evidence":"会让早期事件留下多久"},"inputOutput":{"answer":"输入单位脉冲与保留率 Ā，输出各距离 d 的残留贡献 Āᵈ。","evidence":"状态贡献 Āᵈ"},"mechanism":{"answer":"每过一步再乘一次保留率，故 0.5 比 0.9 衰减得更快。","evidence":"早期输入贡献按 Āᵈ 衰减"},"interpretation":{"answer":"距离十时 0.5 仅剩 0.001，而 0.9 仍有 0.349。","evidence":"保留率 0.9 仍保留 0.349"},"boundary":{"answer":"固定衰减只是线性示例，选择性会让不同输入采用不同时间尺度。","evidence":"不同输入拥有不同时间尺度"}},{"section":6,"definition":{"answer":"线性复杂度表示序列计算随长度 n 近似按一次方增长。","evidence":"线性复杂度不等于实际必然更快"},"problem":{"answer":"它区分渐近复杂度优势与目标硬件上的真实墙钟性能。","evidence":"为什么短序列上仍可能输"},"inputOutput":{"answer":"输入目标长度、batch、硬件和实现，输出吞吐、延迟、显存与质量。","evidence":"tokens/s、延迟与显存"},"mechanism":{"answer":"SSM 用 scan 和固定推理状态避免位置两两匹配，但内核常数仍重要。","evidence":"依赖高效 scan/融合"},"interpretation":{"answer":"O(n) 只说明增长趋势，短序列时常数与利用率可令注意力更快。","evidence":"常数项和硬件利用率可压过复杂度优势"},"boundary":{"answer":"必须在实际硬件、长度和批量上实测，不能仅凭复杂度符号选型。","evidence":"必须在目标硬件、长度和 batch 上测"}},{"section":7,"definition":{"answer":"状态稳定性描述递推在很长步数后是衰减、漂移还是爆炸。","evidence":"状态稳定性决定长外推是否可信"},"problem":{"answer":"它解释训练长度正常的模型在更长序列上为何可能失真。","evidence":"推到 100k 为什么可能漂移或爆炸"},"inputOutput":{"answer":"输入不同长度、零输入、脉冲和数值精度，输出状态与任务曲线。","evidence":"FP32/BF16/FP16 的状态差异"},"mechanism":{"answer":"谱半径大于一放大状态，远小于一快速遗忘，有限精度累积误差。","evidence":"特征值绝对值的最大值"},"interpretation":{"answer":"零输入滚动若持续增大表明动力学或数值实现存在不稳定。","evidence":"状态是否衰减、漂移或爆炸"},"boundary":{"answer":"训练区间稳定不能推出任意长度稳定，必须单独做长度外推压力测试。","evidence":"训练区间内稳定不等于任意长度稳定"}},{"section":8,"definition":{"answer":"随机访问能力是从长历史中精确找回指定旧内容或位置。","evidence":"精确复制与任意检索"},"problem":{"answer":"它揭示有限状态能概括趋势却可能丢失大量互不相关细节。","evidence":"无法同时保存大量互不相关细节"},"inputOutput":{"answer":"输入含目标片段和大量干扰的长序列，输出目标内容及原位置。","evidence":"把一个目标片段藏在大量干扰文本中再要求找回"},"mechanism":{"answer":"所有历史压入固定状态会竞争容量，选择性只能改善写入而不能无限扩容。","evidence":"没有让有限状态变成无限数据库"},"interpretation":{"answer":"能放下百万 token 与仍能精确取回它们是两个不同能力指标。","evidence":"信息仍可取回"},"boundary":{"answer":"精确回看可交给稀疏注意力或外部检索，形成压缩与访问混合架构。","evidence":"稀疏注意力或外部检索负责精确回看"}},{"section":9,"definition":{"answer":"SSM 与 RNN 共享递归状态，与长卷积在线性时不变条件下等价。","evidence":"与 RNN、卷积和注意力的关系"},"problem":{"answer":"该定位帮助按流式状态、长动力学或精确回看需求选择机制。","evidence":"更匹配的机制"},"inputOutput":{"answer":"输入任务的信息访问模式，输出更适合的 RNN、SSM、卷积或注意力。","evidence":"固定小状态、流式"},"mechanism":{"answer":"现代 SSM 通过连续离散化、结构化矩阵和并行扫描提升训练效率。","evidence":"结构化矩阵和并行扫描"},"interpretation":{"answer":"固定状态适合流式，注意力或检索更适合任意位置精确回看。","evidence":"任意位置精确回看"},"boundary":{"answer":"选择性跨越固定卷积核，但仍不是显式保留每个旧位置的注意力。","evidence":"注意力则显式保留位置表示"}},{"section":11,"definition":{"answer":"SSM 运行状态是当前会话此前输入的压缩记忆，具有明确生命周期。","evidence":"部署时状态必须拥有明确生命周期"},"problem":{"answer":"它防止跨用户状态泄漏、批处理错位和故障恢复后的持续污染。","evidence":"不能把一个用户的 SSM 状态直接交给下一位用户"},"inputOutput":{"answer":"输入会话 token 与专属旧状态，输出新 token 结果及该会话新状态。","evidence":"每条序列各自的状态顺序"},"mechanism":{"answer":"按会话租户隔离，支持重置、超时回收、版本迁移和受信检查点重建。","evidence":"支持显式重置、超时回收和模型版本迁移"},"interpretation":{"answer":"一次批状态错位会让后续递推持续受错误历史影响，而非只错一步。","evidence":"后续输出持续污染"},"boundary":{"answer":"未知来源旧状态不得静默复用，故障后应从受信检查点恢复。","evidence":"不是静默复用来源不明的旧状态"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>从连续方程推到离散递推；手算状态的衰减与累积；解释递推—卷积二重视角；判断选择性与随机访问的边界。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>状态空间来自“输入驱动的动态系统”<span class=\"dd-badge math\">连续形式</span></h2><p class=\"dd-lead\">一段历史怎样被压成有限维状态？</p><div class=\"dd-formula\">ḣ(t)=Ah(t)+Bx(t)，　y(t)=Ch(t)+Dx(t)</div><p><b>先读符号：</b><code>t</code> 是连续时间；<code>x(t)</code> 是当前输入，<code>h(t)</code> 是概括此前历史的有限维状态，<code>ḣ(t)</code> 是状态随时间的变化率，<code>y(t)</code> 是当前输出。矩阵 <code>A</code> 决定状态自身怎样演化，<code>B</code> 把输入写入状态，<code>C</code> 从状态读出输出，<code>D</code> 提供输入到输出的直通路径。经典控制系统里这些矩阵描述物理动态；序列模型中它们被学习，用于保存对任务有用的历史。</p><div class=\"dd-note\"><b>贯穿例子：</b>监测机器温度，状态每天保留 80% 旧影响并吸收当天异常：hₜ=0.8hₜ₋₁+xₜ，输入 x=[1,0,2]，h₀=0。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>手算离散化后的序列递推<span class=\"dd-badge math\">离散化</span></h2><p class=\"dd-lead\">采样间隔改变时，为什么不能总沿用同一个 A？</p><div class=\"dd-formula\">hₖ=Āhₖ₋₁+B̄xₖ，　Ā=e<sup>ΔA</sup></div><p><b>式子含义：</b><code>k</code> 是离散时间步，<code>xₖ</code> 是第 k 步输入，<code>hₖ₋₁</code> 与 <code>hₖ</code> 是更新前后的状态；横线表示连续矩阵离散化后的 <code>Ā</code> 与 <code>B̄</code>，<code>Δ</code> 是采样步长。符号 e 表示自然指数函数，e 的 ΔA 次矩阵幂称为矩阵指数，它把连续演化 A 换算为一步状态转移。零阶保持等离散化方法会同时计算 Ā、B̄。若采样频率改变而不重算，模型代表的时间尺度就变了。学习时还要约束状态动力学，避免反复递推导致爆炸。</p><p>本节沿用输入 x=[1,0,2] 和初始状态 h₀=0，并把连续系统离散化成下面的标量递推。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>t</th><th>xₜ</th><th>递推</th><th>hₜ</th></tr></thead><tbody><tr><td>1</td><td>1</td><td>0.8×0+1</td><td>1</td></tr><tr><td>2</td><td>0</td><td>0.8×1</td><td>0.8</td></tr><tr><td>3</td><td>2</td><td>0.8×0.8+2</td><td>2.64</td></tr></tbody></table></div><p>表中采用贯穿例子的标量参数 Ā=0.8、B̄=1：第三步把上一步状态 0.8 衰减为 0.64，再加当前输入 2，得到 2.64。这个数同时含有过去的衰减记忆和当前输入。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>同一线性 SSM 也可以看成一维卷积<span class=\"dd-badge math\">等价视角</span></h2><p class=\"dd-lead\">递归难并行，训练时如何一次处理整段？</p><p>反复代入可得：</p><div class=\"dd-formula\">yₖ=Σ<sub>i=0…k</sub> CĀ<sup>i</sup>B̄ · xₖ₋ᵢ，　Kᵢ=CĀ<sup>i</sup>B̄</div><p><b>符号说明：</b><code>yₖ</code> 是第 k 步输出，<code>i</code> 是回看距离，<code>Σ</code> 把从当前到最早位置的贡献相加；<code>xₖ₋ᵢ</code> 是 i 步前的输入，<code>Āⁱ</code> 表示状态转移重复 i 次。矩阵 B̄ 负责把历史输入写入状态，矩阵 C 负责从状态读出输出。于是 <code>Kᵢ=CĀⁱB̄</code> 就是距离 i 对应的卷积核系数，整组 K 是由状态动力学生成的长卷积核。推理时保留 h 做 O(1) 增量更新；训练时可构造卷积核并用并行卷积/扫描处理整段。结构化参数化让长核计算可行。</p><div class=\"dd-note\"><b>二重性：</b>递推和卷积不是两个模型，而是同一线性系统的两种计算顺序；选择哪种取决于训练吞吐还是流式延迟。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>选择性让模型按内容决定写入与遗忘<span class=\"dd-badge math\">Mamba</span></h2><p class=\"dd-lead\">固定卷积核为何难处理“只记住红色 token”这类内容依赖任务？</p><p>“线性时不变”是指每个位置都复用同一组 A、B、C，所以无论当前 token 是红色标记还是普通词，记忆规则都不变。选择性 SSM 让 Δ、B 或 C 由 xₜ 产生，使相同距离的输入能被不同程度保留：</p><div class=\"dd-formula\">Δₜ,Bₜ,Cₜ=fθ(xₜ)，　hₜ=Ā(Δₜ)hₜ₋₁+B̄ₜxₜ</div><p><b>式中：</b><code>xₜ</code> 是当前输入，<code>fθ</code> 是参数为 θ 的小型可学习函数，它输出当前位置的步长 <code>Δₜ</code>、写入参数 <code>Bₜ</code> 和读出参数 <code>Cₜ</code>；<code>Ā(Δₜ)</code> 是由当前步长得到的离散状态转移，<code>B̄ₜ</code> 是对应离散写入参数，<code>hₜ₋₁</code> 与 <code>hₜ</code> 是更新前后状态。这破坏了固定卷积核的简单形式，需要硬件友好的并行 scan（按递推依赖批量合并各步的扫描算法）内核。内容选择力增强，但模型仍把历史压进有限状态。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>原创演示：遗忘门改变脉冲的有效记忆长度<span class=\"dd-badge math\">可视化</span></h2><p class=\"dd-lead\">0.5 与 0.9 的状态保留率，会让早期事件留下多久？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 720 285\" role=\"img\" aria-label=\"状态空间模型对单次脉冲的两种衰减曲线\"><line x1=\"65\" y1=\"230\" x2=\"675\" y2=\"230\" stroke=\"#7d8797\"/><line x1=\"65\" y1=\"230\" x2=\"65\" y2=\"42\" stroke=\"#7d8797\"/><polyline points=\"85,65 175,148 265,190 355,211 445,220 535,225 625,228\" fill=\"none\" stroke=\"#cf7c72\" stroke-width=\"3\"/><polyline points=\"85,65 175,82 265,97 355,110 445,122 535,133 625,143\" fill=\"none\" stroke=\"#65a6d9\" stroke-width=\"3\"/><circle cx=\"85\" cy=\"65\" r=\"5\" fill=\"#d3a05a\"/><text x=\"102\" y=\"58\" class=\"svg-t\">x₀=1 脉冲</text><text x=\"500\" y=\"119\" class=\"svg-t\" fill=\"#65a6d9\">Ā=0.9</text><text x=\"420\" y=\"210\" class=\"svg-t\" fill=\"#cf7c72\">Ā=0.5</text><text x=\"365\" y=\"258\" text-anchor=\"middle\" class=\"svg-t\">离脉冲的步数</text><text x=\"75\" y=\"32\" class=\"svg-t\">状态贡献 Āᵈ</text></svg><figcaption>图 1　固定保留率下，早期输入贡献按 Āᵈ 衰减；选择性机制相当于让不同输入拥有不同时间尺度。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>距离 d</th><th>0.5ᵈ</th><th>0.9ᵈ</th></tr></thead><tbody><tr><td>1</td><td>0.500</td><td>0.900</td></tr><tr><td>5</td><td>0.031</td><td>0.590</td></tr><tr><td>10</td><td>0.001</td><td>0.349</td></tr><tr><td>50</td><td>≈0</td><td>0.005</td></tr></tbody></table></div><p>距离为 10 步时，保留率 0.5 的贡献只剩 0.001，而保留率 0.9 仍保留 0.349；曲线越缓，单次事件的有效记忆长度越长。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>线性复杂度不等于实际必然更快<span class=\"dd-badge eng\">系统</span></h2><p class=\"dd-lead\">O(n) 赢了 O(n²)，为什么短序列上仍可能输？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>因素</th><th>SSM</th><th>注意力</th></tr></thead><tbody><tr><td>渐近序列计算</td><td>O(n)</td><td>O(n²)</td></tr><tr><td>推理状态</td><td>固定维度</td><td>KV 随 n 增长</td></tr><tr><td>训练内核</td><td>依赖高效 scan/融合</td><td>成熟矩阵与 FlashAttention</td></tr><tr><td>随机访问旧位置</td><td>经压缩状态间接访问</td><td>可直接注意旧 KV</td></tr></tbody></table></div><p>短序列、较小批量或缺少优化内核时，常数项和硬件利用率可压过复杂度优势。必须在目标硬件、长度和 batch 上测 tokens/s、延迟与显存。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>状态稳定性决定长外推是否可信<span class=\"dd-badge eng\">数值边界</span></h2><p class=\"dd-lead\">训练长度 4k 正常，推到 100k 为什么可能漂移或爆炸？</p><p>矩阵的“谱半径”是其特征值绝对值的最大值，可粗略理解为状态反复乘这个转移矩阵时最容易放大还是衰减。若离散 Ā 的谱半径大于 1，微小状态会随步数放大；远小于 1 又会迅速遗忘。有限精度、归一化和输入依赖步长会使长程误差累积。训练区间内稳定不等于任意长度稳定。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>测试</th><th>观察</th></tr></thead><tbody><tr><td>长度外推</td><td>loss/准确率随长度曲线</td></tr><tr><td>零输入滚动</td><td>状态是否衰减、漂移或爆炸</td></tr><tr><td>脉冲响应</td><td>不同时间尺度是否可解释</td></tr><tr><td>精度切换</td><td>FP32/BF16/FP16 的状态差异</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>压缩历史会伤害精确复制与任意检索<span class=\"dd-badge intuition\">能力边界</span></h2><p class=\"dd-lead\">能处理百万长度，是否等于能找回任意一个旧 token？</p><p>固定状态可概括趋势，却可能无法同时保存大量互不相关细节。密码复制、键值关联、“needle-in-a-haystack”（把一个目标片段藏在大量干扰文本中再要求找回）和需要引用原文位置的任务，是检验随机访问的压力测试。选择性可改善写入策略，但没有让有限状态变成无限数据库。</p><p>混合架构可用 SSM 负责局部/流式压缩，稀疏注意力或外部检索负责精确回看。评测应区分“输入放得下”“吞吐可扩展”和“信息仍可取回”。</p><div class=\"dd-note warn\"><b>长上下文长度不是记忆证明。</b>必须按距离、干扰数量和检索精度报告能力。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>与 RNN、卷积和注意力的关系<span class=\"dd-badge intuition\">定位</span></h2><p class=\"dd-lead\">SSM 是旧 RNN 换名字，还是长卷积的一种？</p><p>它们共享递归状态思想，但现代 SSM 用连续系统离散化、结构化矩阵和并行扫描解决训练效率；线性时不变 SSM 又等价于特定长卷积。选择性 SSM 引入内容依赖，跨越固定卷积核。注意力则显式保留位置表示并做内容寻址。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>需求</th><th>更匹配的机制</th></tr></thead><tbody><tr><td>固定小状态、流式</td><td>RNN/SSM</td></tr><tr><td>超长平滑动力学</td><td>结构化 SSM</td></tr><tr><td>任意位置精确回看</td><td>注意力/检索</td></tr><tr><td>局部平移模式</td><td>卷积</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">从动态系统和计算实现两侧同时理解。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>线性时间就必然更快</td><td>内核、长度、批量和硬件决定墙钟性能</td></tr><tr><td>状态保留完整历史</td><td>它是有限维有损压缩</td></tr><tr><td>递推与卷积是两种模型</td><td>线性时不变 SSM 中是等价计算视角</td></tr><tr><td>选择性解决所有检索</td><td>它改善内容写入，未消除容量边界</td></tr><tr><td>训练稳定即可无限外推</td><td>需做长度与数值稳定压力测试</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>RNN、线性代数、卷积、离散系统</td></tr><tr><td><b>本页核心</b></td><td>离散化、卷积等价、选择性扫描、稳定性</td></tr><tr><td>对比</td><td>注意力、Transformer、长上下文</td></tr><tr><td>工程</td><td>并行 scan、融合内核、流式推理</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">11</span>部署时状态必须拥有明确生命周期<span class=\"dd-badge eng\">运行约束</span></h2><p class=\"dd-lead\">为什么不能把一个用户的 SSM 状态直接交给下一位用户？</p><p>递归状态包含此前输入的压缩信息，必须按会话与租户隔离，支持显式重置、超时回收和模型版本迁移。批处理调度还要保存每条序列各自的状态顺序；错位一次就会让后续输出持续污染。故障恢复应从受信检查点重建，而不是静默复用来源不明的旧状态。</p></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">12</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>连续动力学定义状态演化</li><li>按采样步长离散化</li><li>递推或卷积处理序列</li><li>选择性参数按内容控制记忆</li><li>融合扫描实现线性吞吐</li><li>以检索、外推和硬件实测验收</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">13</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>例子中 h₃ 为什么是2.64？</li><li>线性 SSM 的卷积核第 i 项是什么？</li><li>选择性主要改变什么？</li><li>O(n) 为何不保证短序列更快？</li><li>百万上下文为何不证明百万长度检索？</li><li>假设“状态空间模型 SSM：用可控动态系统压缩长序列”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“状态空间模型 SSM：用可控动态系统压缩长序列”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>h₃=0.8×0.8+2=2.64。</li><li>Kᵢ=CĀⁱB̄。</li><li>让步长或写入/读出参数依赖当前输入，从而按内容保留信息。</li><li>内核成熟度、常数项、并行利用率和数据搬运可能主导。</li><li>有限状态可能有损压缩细节，必须独立测精确回看。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2111.00396\" target=\"_blank\" rel=\"noopener\">Efficiently Modeling Long Sequences with Structured State Spaces</a>：S4 结构化状态空间</li><li><a href=\"https://arxiv.org/abs/2208.04933\" target=\"_blank\" rel=\"noopener\">Simplified State Space Layers for Sequence Modeling</a>：S5 与并行扫描</li><li><a href=\"https://arxiv.org/abs/2312.00752\" target=\"_blank\" rel=\"noopener\">Mamba: Linear-Time Sequence Modeling with Selective State Spaces</a>：选择性 SSM</li><li><a href=\"https://arxiv.org/abs/2405.21060\" target=\"_blank\" rel=\"noopener\">Transformers are SSMs</a>：结构化状态空间二重性</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
